function getWeaponNextSteps(gameId: GameId) {
  if (gameId === 'wuwa') return WUWA_WEAPON_NEXT_STEPS;
  if (gameId === 'zzz') return ZZZ_WEAPON_NEXT_STEPS;
  if (gameId === 'endfield') return ENDFIELD_WEAPON_NEXT_STEPS;
